import sys

def main():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return

    n = int(data[0])
    current_reserver = None

    for i in range(1, n + 1):
        parts = data[i].split()
        if len(parts) != 2:
            continue

        action = parts[0]
        emp_id = int(parts[1])

        if action == "RESERVE":
            if current_reserver is None:
                current_reserver = emp_id
                print("Room Reserved")
            elif current_reserver == emp_id:
                print("Room Reserved")
            else:
                print(f"Room Already Reserved by Employee {current_reserver}")
        elif action == "FREE":
            if current_reserver is None:
                print("No Reservation to Free")
            elif current_reserver == emp_id:
                current_reserver = None
                print("Room Freed")
            else:
                print("No Reservation to Free")

if __name__ == "__main__":
    main()
